CREATE TABLE dance_publication_starts(community_id TEXT NOT NULL, account_id TEXT NOT NULL, command_id TEXT NOT NULL, original_hash TEXT NOT NULL, capture_id TEXT NOT NULL UNIQUE, reserved_at_ms INTEGER NOT NULL CHECK(reserved_at_ms>0), PRIMARY KEY(community_id,account_id,command_id));
CREATE TRIGGER dance_publication_start_no_update BEFORE UPDATE ON dance_publication_starts BEGIN SELECT RAISE(ABORT,'dance_publication_start_immutable'); END;
CREATE TRIGGER dance_publication_start_no_delete BEFORE DELETE ON dance_publication_starts BEGIN SELECT RAISE(ABORT,'dance_publication_start_immutable'); END;
CREATE TRIGGER dance_publication_start_no_replace BEFORE INSERT ON dance_publication_starts WHEN EXISTS(SELECT 1 FROM dance_publication_starts WHERE (community_id=NEW.community_id AND account_id=NEW.account_id AND command_id=NEW.command_id) OR capture_id=NEW.capture_id) BEGIN SELECT RAISE(ABORT,'dance_publication_start_immutable'); END;
CREATE TABLE dance_publication_bindings(community_id TEXT NOT NULL,capture_id TEXT NOT NULL,capture_hash TEXT NOT NULL,account_id TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN('dance-verdict','dance-review-attribution')),command_id TEXT NOT NULL REFERENCES publication_v1_commands(command_id),value_json TEXT NOT NULL CHECK(json_valid(value_json)),PRIMARY KEY(community_id,capture_id,account_id,purpose),UNIQUE(capture_hash,account_id,purpose));
CREATE TRIGGER dance_publication_binding_insert BEFORE INSERT ON dance_publication_bindings WHEN EXISTS(SELECT 1 FROM dance_publication_bindings WHERE (community_id=NEW.community_id AND capture_id=NEW.capture_id AND account_id=NEW.account_id AND purpose=NEW.purpose) OR (capture_hash=NEW.capture_hash AND account_id=NEW.account_id AND purpose=NEW.purpose)) BEGIN SELECT RAISE(ABORT,'dance_publication_binding_immutable'); END;
CREATE TRIGGER dance_publication_binding_update BEFORE UPDATE ON dance_publication_bindings BEGIN SELECT RAISE(ABORT,'dance_publication_binding_immutable'); END;
CREATE TRIGGER dance_publication_binding_delete BEFORE DELETE ON dance_publication_bindings BEGIN SELECT RAISE(ABORT,'dance_publication_binding_immutable'); END;
CREATE TABLE dance_v2_action_originals(community_id TEXT NOT NULL,capture_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('register','verdict')),account_id TEXT NOT NULL,command_id TEXT NOT NULL UNIQUE,request_sha256 TEXT NOT NULL,bound_at_ms INTEGER NOT NULL CHECK(bound_at_ms>0),input_json TEXT NOT NULL CHECK(json_valid(input_json)),context_sha256 TEXT NOT NULL,PRIMARY KEY(community_id,capture_id,kind));
CREATE TABLE dance_v2_ready_commands(command_id TEXT PRIMARY KEY REFERENCES dance_v2_action_originals(command_id),source_hash TEXT NOT NULL,publisher TEXT NOT NULL,command_hash TEXT NOT NULL,encoded TEXT NOT NULL,calldata TEXT NOT NULL,resource_id TEXT NOT NULL);
CREATE TABLE dance_v2_dispatch_sessions(command_id TEXT PRIMARY KEY REFERENCES dance_v2_ready_commands(command_id),session_sha256 TEXT NOT NULL);
CREATE TRIGGER dance_v2_action_originals_no_update BEFORE UPDATE ON dance_v2_action_originals BEGIN SELECT RAISE(ABORT,'dance_v2_action_immutable'); END;
CREATE TRIGGER dance_v2_action_originals_no_delete BEFORE DELETE ON dance_v2_action_originals BEGIN SELECT RAISE(ABORT,'dance_v2_action_immutable'); END;
CREATE TRIGGER dance_v2_action_originals_no_replace BEFORE INSERT ON dance_v2_action_originals WHEN EXISTS(SELECT 1 FROM dance_v2_action_originals WHERE command_id=NEW.command_id OR (community_id=NEW.community_id AND capture_id=NEW.capture_id AND kind=NEW.kind)) BEGIN SELECT RAISE(ABORT,'dance_v2_action_immutable'); END;
CREATE TRIGGER dance_v2_ready_commands_no_update BEFORE UPDATE ON dance_v2_ready_commands BEGIN SELECT RAISE(ABORT,'dance_v2_action_immutable'); END;
CREATE TRIGGER dance_v2_ready_commands_no_delete BEFORE DELETE ON dance_v2_ready_commands BEGIN SELECT RAISE(ABORT,'dance_v2_action_immutable'); END;
CREATE TRIGGER dance_v2_ready_commands_no_replace BEFORE INSERT ON dance_v2_ready_commands WHEN EXISTS(SELECT 1 FROM dance_v2_ready_commands WHERE command_id=NEW.command_id) BEGIN SELECT RAISE(ABORT,'dance_v2_action_immutable'); END;
CREATE TRIGGER dance_v2_dispatch_sessions_no_update BEFORE UPDATE ON dance_v2_dispatch_sessions BEGIN SELECT RAISE(ABORT,'dance_v2_action_immutable'); END;
CREATE TRIGGER dance_v2_dispatch_sessions_no_delete BEFORE DELETE ON dance_v2_dispatch_sessions BEGIN SELECT RAISE(ABORT,'dance_v2_action_immutable'); END;
CREATE TRIGGER dance_v2_dispatch_sessions_no_replace BEFORE INSERT ON dance_v2_dispatch_sessions WHEN EXISTS(SELECT 1 FROM dance_v2_dispatch_sessions WHERE command_id=NEW.command_id) BEGIN SELECT RAISE(ABORT,'dance_v2_action_immutable'); END;
